package protocol

import (
	"encoding/binary"
	"math"
	"testing"
)

// The geometry must match the app's src/lib/protocol/history.ts exactly —
// both ends compute tiles independently and meet on the etag. The reference
// values below were generated by running the app's own functions, so a
// mismatch here is a genuine wire break, not a test opinion.

func TestTileGeometryMatchesTheApp(t *testing.T) {
	if got := PointsPerTile(ResN5m); got != 144 {
		t.Fatalf("5m tile has %d points, the app says 144", got)
	}
	if got := PointsPerTile(ResN1h); got != 168 {
		t.Fatalf("1h tile has %d points, the app says 168", got)
	}

	// tileId: res/stride/tileIndex, epoch-aligned.
	at := int64(1_760_000_000_000)
	start := TileStartFor(ResN5m, at)
	if start%43_200_000 != 0 || start > at || at-start >= 43_200_000 {
		t.Fatalf("5m tile start %d is not the aligned tile containing %d", start, at)
	}
	if got, want := TileIDFor(ResN5m, 3, start), "5m/3/40740"; got != want {
		t.Fatalf("tileID = %q, want %q", got, want)
	}
}

func TestEtagMatchesTheAppByteForByte(t *testing.T) {
	// Values from the app's etagOf(), run on the same input.
	ascending := make([]byte, 16)
	for i := range ascending {
		ascending[i] = byte(i)
	}
	if got := EtagOf(ascending); got != "c8fff215" {
		t.Fatalf("etag([0..15]) = %s, the app computes c8fff215", got)
	}
	if got := EtagOf(nil); got != "811c9dc5" {
		t.Fatalf("etag(empty) = %s, the app computes 811c9dc5", got)
	}
}

// PackTile folds stored buckets into strided points by plain mean, marks holes
// as MissingSample and keeps a real reading off that value. Two 5m buckets at
// stride 2 make one point; a bucket outside the tile is not counted.
func TestPackTileFoldsMeansAndMarksHoles(t *testing.T) {
	start := TileStartFor(ResN5m, 1_760_000_000_000)
	step := ResolutionStepMs[ResN5m]
	windows := map[string][]HistorySample{
		"grid_w": {
			{StartMs: start, W: 100},
			{StartMs: start + step, W: 201},
			{StartMs: start - step, W: 9_999},
		},
		"pv_w": {
			{StartMs: start + 2*step, W: -1e12},
		},
	}
	series := []string{"grid_w", "pv_w"}
	chunk := PackTile(ResN5m, 2, start, series, windows, start+step)

	points := PointsPerTile(ResN5m) / 2
	if want := int64(len(series)) * points * 4; int64(len(chunk.Data)) != want {
		t.Fatalf("data is %d bytes, want %d", len(chunk.Data), want)
	}
	at := func(s, p int64) int32 {
		return int32(binary.LittleEndian.Uint32(chunk.Data[(s*points+p)*4:]))
	}
	if got := at(0, 0); got != 151 {
		t.Fatalf("grid point 0 = %d, want the rounded mean 151", got)
	}
	if got := at(0, 1); got != MissingSample {
		t.Fatalf("grid point 1 = %d, want MissingSample", got)
	}
	if got := at(1, 1); got != math.MinInt32+1 {
		t.Fatalf("pv point 1 = %d, want one step above MissingSample", got)
	}
	if chunk.TileID != TileIDFor(ResN5m, 2, start) || chunk.StepMs != 2*step || chunk.Res != ResN5m {
		t.Fatalf("chunk header = %s step %d res %s", chunk.TileID, chunk.StepMs, chunk.Res)
	}
	if chunk.Etag != EtagOf(chunk.Data) || !chunk.Partial {
		t.Fatalf("etag %s partial %v", chunk.Etag, chunk.Partial)
	}
	if closed := PackTile(ResN5m, 2, start, series, windows, start+ResolutionTileSpanMs[ResN5m]); closed.Partial {
		t.Fatal("a tile that ended at nowMs is still partial")
	}
}
